// Replace the former envelope and diya sequence with the Banaras temple entrance.
document.querySelectorAll('.envelope-petals,.flower-shower').forEach(el=>el.remove());gate.inert=true;document.body.style.overflow='hidden';heroArtwork.src='banaras-couple-night.png';heroArtwork.alt='A wedding couple looking toward illuminated Banaras ghats across the Ganga at night';document.querySelector('.hero .hero-inner>.eyebrow').textContent='॥ हर हर महादेव ॥';
const entry=document.createElement('div');entry.className='banaras-entry';entry.setAttribute('role','dialog');entry.setAttribute('aria-modal','true');entry.setAttribute('aria-label','Open the temple doors for Dhiraj and Neha wedding invitation');entry.innerHTML='<div class="banaras-reveal"></div><div class="banaras-gate-art"></div><div class="banaras-door left"></div><div class="banaras-door right"></div><button class="temple-open-control">Tap to open the doors</button><div class="banaras-welcome"><p>Welcome to the wedding of</p><h2>Dhiraj & Neha</h2><img src="krishna-wedding-ornament.svg" alt="Gold wedding ornament"><p class="location">UTTAR PRADESH</p></div><button class="banaras-continue">Read the invitation ↓</button>';document.body.append(entry);let templeOpened=false;const openTemple=()=>{if(templeOpened)return;templeOpened=true;entry.classList.add('opened');if(weddingAudio.paused)weddingAudio.play().then(syncMusic).catch(()=>syncMusic());setTimeout(()=>{entry.classList.add('names-ready');entry.querySelector('.banaras-continue').focus()},motion?100:2900)};entry.querySelector('.temple-open-control').onclick=openTemple;entry.querySelector('.banaras-continue').onclick=()=>{entry.classList.add('dismissed');document.body.style.overflow='';document.querySelector('.hero h1').focus({preventScroll:true});setTimeout(()=>entry.remove(),1300);showerFlowers()};entry.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();entry.querySelector(templeOpened?'.banaras-continue':'.temple-open-control').focus()}});entry.querySelector('.temple-open-control').focus();
function sizeTempleDoors(){const w=entry.clientWidth,h=entry.clientHeight,s=Math.max(w/1051,h/1497),iw=1051*s,ih=1497*s,ox=(w-iw)/2,oy=(h-ih)/2;const left=ox+iw*.15,middle=ox+iw*.5,right=ox+iw*.84,top=oy+ih*.223,bottom=oy+ih*.88;Object.entries({'--gate-width':iw,'--gate-height':ih,'--door-left':left,'--door-middle':middle,'--door-right':right,'--door-top':top,'--door-bottom':bottom,'--door-width':(right-left)/2,'--door-height':bottom-top,'--left-bg-x':ox-left,'--right-bg-x':ox-middle,'--door-bg-y':oy-top}).forEach(([key,value])=>entry.style.setProperty(key,value+'px'))}sizeTempleDoors();addEventListener('resize',sizeTempleDoors);
